// ---------------------------------------------------------------- search: full text, click to fly there
let docs = [];
function buildIndex() {
  docs = space.nodes.map((n, i) => ({ i, title: (n.title ?? "").toLowerCase(), all: [n.title, n.summary, n.text, n.output, n.group].join("\n").toLowerCase() }));
